fun KitchenScale.weights(): Flow<Weight> = callbackFlow {
    val subscription = subscribe(
        onWeight = { weight -> trySend(weight) },      // never blocks the scale's thread
        onFailure = { error -> close(error) },         // collect throws this error
    )
    awaitClose { subscription.cancel() }               // on take(n), cancellation, close and error
}.buffer(1_000)                                        // fused into the callbackFlow's channel

